CREATE FUNCTION pg_temp.hw_apply_0(p_key TEXT, p_data JSONB) RETURNS VOID LANGUAGE plpgsql AS $heroeswatch_37$
DECLARE
  incoming "heroes_watch"."Game"%ROWTYPE;
  existing "heroes_watch"."Game"%ROWTYPE;
BEGIN
  incoming := jsonb_populate_record(NULL::"heroes_watch"."Game", p_data);
  SELECT * INTO existing FROM "heroes_watch"."Game" WHERE "Game_id" = incoming."Game_id";
  IF FOUND THEN
    IF incoming."Game_id" IS NOT NULL AND existing."Game_id" IS NOT NULL AND incoming."Game_id" IS DISTINCT FROM existing."Game_id" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'Game', p_key, E'Game_id';
    END IF;
    IF incoming."SeriesCode" IS NOT NULL AND existing."SeriesCode" IS NOT NULL AND incoming."SeriesCode" IS DISTINCT FROM existing."SeriesCode" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'Game', p_key, E'SeriesCode';
    END IF;
    IF incoming."DisplayOrder" IS NOT NULL AND existing."DisplayOrder" IS NOT NULL AND incoming."DisplayOrder" IS DISTINCT FROM existing."DisplayOrder" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'Game', p_key, E'DisplayOrder';
    END IF;
    IF incoming."Name" IS NOT NULL AND existing."Name" IS NOT NULL AND incoming."Name" IS DISTINCT FROM existing."Name" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'Game', p_key, E'Name';
    END IF;
    IF incoming."ReleaseDate" IS NOT NULL AND existing."ReleaseDate" IS NOT NULL AND incoming."ReleaseDate" IS DISTINCT FROM existing."ReleaseDate" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'Game', p_key, E'ReleaseDate';
    END IF;
    IF incoming."Description" IS NOT NULL AND existing."Description" IS NOT NULL AND incoming."Description" IS DISTINCT FROM existing."Description" THEN
      RAISE EXCEPTION 'Content conflict: %/%.%; existing non-null value retained and import rolled back.', E'Game', p_key, E'Description';
    END IF;
    IF (existing."SeriesCode" IS NULL AND incoming."SeriesCode" IS NOT NULL)
      OR (existing."DisplayOrder" IS NULL AND incoming."DisplayOrder" IS NOT NULL)
      OR (existing."Name" IS NULL AND incoming."Name" IS NOT NULL)
      OR (existing."ReleaseDate" IS NULL AND incoming."ReleaseDate" IS NOT NULL)
      OR (existing."Description" IS NULL AND incoming."Description" IS NOT NULL) THEN
      UPDATE "heroes_watch"."Game" SET "SeriesCode" = COALESCE(existing."SeriesCode", incoming."SeriesCode"),
        "DisplayOrder" = COALESCE(existing."DisplayOrder", incoming."DisplayOrder"),
        "Name" = COALESCE(existing."Name", incoming."Name"),
        "ReleaseDate" = COALESCE(existing."ReleaseDate", incoming."ReleaseDate"),
        "Description" = COALESCE(existing."Description", incoming."Description")
      WHERE "Game_id" = incoming."Game_id";
    END IF;
  ELSE
    INSERT INTO "heroes_watch"."Game" ("Game_id", "SeriesCode", "DisplayOrder", "Name", "ReleaseDate", "Description")
    OVERRIDING SYSTEM VALUE
